UNION ALL SELECT 'ndv(orders.o_orderkey | orders)' AS fact, (SELECT count(*) FROM (SELECT DISTINCT orders.o_orderkey FROM orders AS "orders")) AS value
UNION ALL SELECT 'ndv(orders.o_orderkey | orders where CAST(orders.o_orderdate AS TIMESTAMP) < CAST(''1993-10-01 00:00:00'' AS TIMESTAMP) and orders.o_orderdate >= CAST(''1993-07-01'' AS DATE))' AS fact, (SELECT count(*) FROM (SELECT DISTINCT orders.o_orderkey FROM orders AS "orders" WHERE (CAST(orders.o_orderdate AS TIMESTAMP) < CAST('1993-10-01 00:00:00' AS TIMESTAMP)) AND (orders.o_orderdate >= CAST('1993-07-01' AS DATE)))) AS value
UNION ALL SELECT 'ndv(orders.o_orderpriority | customer × orders where customer.c_custkey <= 1499 and customer.c_custkey = orders.o_custkey and customer.c_mktsegment = ''BUILDING'')' AS fact, (SELECT count(*) FROM (SELECT DISTINCT orders.o_orderpriority FROM customer AS "customer", orders AS "orders" WHERE (customer.c_custkey <= 1499) AND (customer.c_custkey = orders.o_custkey) AND (customer.c_mktsegment = 'BUILDING'))) AS value
UNION ALL SELECT 'ndv("part".p_partkey | lineitem × part where lineitem.l_partkey = "part".p_partkey and "part".p_brand = ''Brand#23'' and "part".p_container = ''MED BOX'')' AS fact, (SELECT count(*) FROM (SELECT DISTINCT "part".p_partkey FROM lineitem AS "lineitem", part AS "part" WHERE (lineitem.l_partkey = "part".p_partkey) AND ("part".p_brand = 'Brand#23') AND ("part".p_container = 'MED BOX'))) AS value
UNION ALL SELECT 'ndv("part".p_partkey | nation × part × partsupp × region × supplier where ends_with("part".p_type, ''BRASS'') and nation.n_nationkey = supplier.s_nationkey and nation.n_regionkey = "region".r_regionkey and "part".p_partkey = partsupp.ps_partkey and "part".p_size = 15 and partsupp.ps_suppkey = supplier.s_suppkey and "region".r_name = ''EUROPE'')' AS fact, (SELECT count(*) FROM (SELECT DISTINCT "part".p_partkey FROM nation AS "nation", part AS "part", partsupp AS "partsupp", region AS "region", supplier AS "supplier" WHERE (ends_with("part".p_type, 'BRASS')) AND (nation.n_nationkey = supplier.s_nationkey) AND (nation.n_regionkey = "region".r_regionkey) AND ("part".p_partkey = partsupp.ps_partkey) AND ("part".p_size = 15) AND (partsupp.ps_suppkey = supplier.s_suppkey) AND ("region".r_name = 'EUROPE'))) AS value
UNION ALL SELECT 'ndv(partsupp.ps_partkey | nation × partsupp × supplier where nation.n_name = ''GERMANY'' and nation.n_nationkey = supplier.s_nationkey and partsupp.ps_suppkey = supplier.s_suppkey)' AS fact, (SELECT count(*) FROM (SELECT DISTINCT partsupp.ps_partkey FROM nation AS "nation", partsupp AS "partsupp", supplier AS "supplier" WHERE (nation.n_name = 'GERMANY') AND (nation.n_nationkey = supplier.s_nationkey) AND (partsupp.ps_suppkey = supplier.s_suppkey))) AS value;
